<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Aid Alliance — Together We Respond</title>
<meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
<style>
/* ── Reset & Base ────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #C41E3A;
  --red-dark: #A01830;
  --navy: #1B3A5C;
  --navy-light: #2A5A8C;
  --white: #FFFFFF;
  --gray-50: #FAFAFA;
  --gray-100: #F5F5F5;
  --gray-200: #E8E8E8;
  --gray-300: #D4D4D4;
  --gray-500: #888;
  --gray-700: #555;
  --gray-900: #1A1A1A;
  --font-heading: 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-body: system-ui, -apple-system, 'Segoe UI', sans-serif;
  --max-width: 1200px;
  --header-h: 72px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: var(--red); text-decoration: none; }
a:hover { text-decoration: underline; }

h1, h2, h3, h4 { font-family: var(--font-heading); line-height: 1.2; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 14px 32px; border-radius: 6px; font-weight: 700; font-size: 1rem;
  border: none; cursor: pointer; transition: all 0.2s; font-family: var(--font-body);
  text-decoration: none; white-space: nowrap;
}
.btn:hover { text-decoration: none; }
.btn-primary { background: var(--red); color: var(--white); }
.btn-primary:hover { background: var(--red-dark); }
.btn-outline { background: transparent; color: var(--white); border: 2px solid var(--white); }
.btn-outline:hover { background: rgba(255,255,255,0.15); }
.btn-outline-dark { background: transparent; color: var(--navy); border: 2px solid var(--navy); }
.btn-outline-dark:hover { background: var(--navy); color: var(--white); }
.btn-white { background: var(--white); color: var(--red); }
.btn-white:hover { background: var(--gray-100); }

/* ── Header ─────────────────────────────────────────────────── */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: var(--white); height: var(--header-h);
  box-shadow: 0 1px 4px rgba(0,0,0,0.08);
}
.header-inner {
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  height: 100%; display: flex; align-items: center; justify-content: space-between;
}
.logo { display: flex; align-items: center; gap: 10px; font-family: var(--font-heading); font-weight: 800; font-size: 1.05rem; color: var(--navy); text-decoration: none; flex-shrink: 0; }
.logo:hover { text-decoration: none; }
.logo-icon { width: 36px; height: 36px; background: var(--red); border-radius: 8px; display: flex; align-items: center; justify-content: center; color: var(--white); font-size: 1.3rem; font-weight: 900; flex-shrink: 0; }

.nav-main { display: flex; align-items: center; gap: 4px; }
.nav-main a {
  padding: 8px 14px; color: var(--gray-700); font-size: 0.92rem;
  font-weight: 500; border-radius: 4px; transition: all 0.15s;
}
.nav-main a:hover { background: var(--gray-100); color: var(--gray-900); text-decoration: none; }
.nav-main .btn-donate { background: var(--red); color: var(--white); margin-left: 8px; padding: 10px 20px; font-size: 0.9rem; }
.nav-main .btn-donate:hover { background: var(--red-dark); }

.utility-nav { font-size: 0.8rem; display: flex; gap: 16px; margin-bottom: 4px; }
.utility-nav a { color: var(--gray-500); }
.utility-nav a:hover { color: var(--gray-700); }

.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 8px; background: none; border: none; z-index: 1001; }
.hamburger span { display: block; width: 24px; height: 2.5px; background: var(--navy); border-radius: 2px; transition: all 0.3s; }
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ── Mobile Nav Drawer ──────────────────────────────────────── */
.mobile-nav {
  position: fixed; top: var(--header-h); left: 0; right: 0; bottom: 0;
  background: var(--white); z-index: 999; transform: translateX(-100%);
  transition: transform 0.3s ease; display: flex; flex-direction: column;
  padding: 24px; overflow-y: auto;
}
.mobile-nav.open { transform: translateX(0); }
.mobile-nav a {
  display: block; padding: 14px 0; font-size: 1.1rem; font-weight: 600;
  color: var(--gray-700); border-bottom: 1px solid var(--gray-200);
}
.mobile-nav .btn-donate { display: inline-flex; margin-top: 16px; }
.mobile-nav .utility-links { margin-top: 24px; display: flex; gap: 16px; flex-wrap: wrap; }
.mobile-nav .utility-links a { font-size: 0.85rem; border: none; font-weight: 400; color: var(--gray-500); padding: 4px 0; }

/* ── Hero ───────────────────────────────────────────────────── */
.hero {
  margin-top: var(--header-h); min-height: 560px;
  background: linear-gradient(135deg, var(--navy) 0%, #0D2137 100%);
  display: flex; align-items: center; position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 600"><rect fill="none"/><circle cx="200" cy="100" r="300" fill="rgba(255,255,255,0.03)"/><circle cx="1000" cy="400" r="400" fill="rgba(196,30,58,0.08)"/></svg>') center/cover no-repeat;
  opacity: 0.6;
}
.hero .container { position: relative; z-index: 1; }
.hero-content { max-width: 640px; padding: 80px 0; }
.hero h1 { font-size: clamp(2.2rem, 5vw, 3.4rem); color: var(--white); margin-bottom: 20px; font-weight: 800; }
.hero p { font-size: 1.15rem; color: rgba(255,255,255,0.85); margin-bottom: 36px; line-height: 1.7; max-width: 520px; }
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

/* ── Section Shared ──────────────────────────────────────────── */
.section { padding: 80px 0; }
.section-label { text-transform: uppercase; font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em; color: var(--red); margin-bottom: 8px; }
.section-title { font-size: clamp(1.8rem, 3.5vw, 2.4rem); color: var(--navy); margin-bottom: 20px; font-weight: 700; }
.section-body { font-size: 1.05rem; color: var(--gray-700); max-width: 720px; line-height: 1.75; }

/* ── Mission ─────────────────────────────────────────────────── */
.mission { background: var(--gray-50); }
.mission-highlight { font-size: 1.15rem; font-weight: 600; color: var(--navy); margin-bottom: 20px; padding-left: 20px; border-left: 4px solid var(--red); }

/* ── Impact Stats ───────────────────────────────────────────── */
.impact-stats { background: var(--red); color: var(--white); }
.impact-stats .section-title { color: var(--white); }
.impact-stats .section-body { color: rgba(255,255,255,0.85); }
.stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-top: 48px; }
.stat-card { text-align: center; }
.stat-number { font-family: var(--font-heading); font-size: clamp(2.4rem, 5vw, 3.2rem); font-weight: 800; line-height: 1.1; }
.stat-label { font-size: 0.95rem; color: rgba(255,255,255,0.85); margin-top: 8px; font-weight: 500; }

/* ── Programs Accordion ──────────────────────────────────────── */
.accordion { max-width: 800px; margin-top: 40px; }
.accordion-item { border-bottom: 1px solid var(--gray-200); }
.accordion-header {
  width: 100%; padding: 22px 0; display: flex; align-items: center;
  justify-content: space-between; background: none; border: none;
  font-size: 1.1rem; font-weight: 700; color: var(--navy);
  cursor: pointer; text-align: left; font-family: var(--font-body);
  transition: color 0.2s;
}
.accordion-header:hover { color: var(--red); }
.accordion-icon {
  width: 28px; height: 28px; border-radius: 50%; display: flex;
  align-items: center; justify-content: center; font-size: 1.4rem;
  color: var(--red); flex-shrink: 0; transition: transform 0.3s;
}
.accordion-item.open .accordion-icon { transform: rotate(45deg); }
.accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.35s ease, padding 0.35s ease; }
.accordion-item.open .accordion-body { max-height: 300px; padding-bottom: 20px; }
.accordion-body p { color: var(--gray-700); font-size: 0.95rem; line-height: 1.7; }

/* ── Get Involved ────────────────────────────────────────────── */
.get-involved { background: var(--gray-50); }
.involve-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; margin-top: 40px; }
.involve-card { background: var(--white); border-radius: 10px; padding: 36px 28px; box-shadow: 0 2px 12px rgba(0,0,0,0.06); transition: transform 0.2s, box-shadow 0.2s; }
.involve-card:hover { transform: translateY(-4px); box-shadow: 0 8px 24px rgba(0,0,0,0.1); }
.involve-icon { width: 52px; height: 52px; border-radius: 12px; background: var(--navy); display: flex; align-items: center; justify-content: center; font-size: 1.5rem; margin-bottom: 20px; color: var(--white); }
.involve-card h3 { font-size: 1.15rem; color: var(--navy); margin-bottom: 10px; }
.involve-card p { color: var(--gray-700); font-size: 0.92rem; line-height: 1.65; margin-bottom: 20px; }
.involve-card .btn { font-size: 0.9rem; padding: 10px 22px; }

/* ── News Carousel ───────────────────────────────────────────── */
.news-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 36px; flex-wrap: wrap; gap: 16px; }
.carousel-controls { display: flex; gap: 8px; }
.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%; border: 2px solid var(--gray-300);
  background: var(--white); cursor: pointer; display: flex; align-items: center;
  justify-content: center; font-size: 1.2rem; color: var(--navy); transition: all 0.2s;
}
.carousel-btn:hover { border-color: var(--red); color: var(--red); }
.carousel-track { overflow: hidden; }
.carousel-slides { display: flex; transition: transform 0.4s ease; }
.news-card { flex: 0 0 calc(50% - 14px); min-width: calc(50% - 14px); margin-right: 28px; background: var(--white); border-radius: 10px; overflow: hidden; box-shadow: 0 2px 12px rgba(0,0,0,0.06); }
.news-card-image { height: 200px; background: var(--navy); display: flex; align-items: center; justify-content: center; color: rgba(255,255,255,0.6); font-size: 2rem; }
.news-card:nth-child(1) .news-card-image { background: linear-gradient(135deg, #1B3A5C, #2A5A8C); }
.news-card:nth-child(2) .news-card-image { background: linear-gradient(135deg, #C41E3A, #E8553D); }
.news-card:nth-child(3) .news-card-image { background: linear-gradient(135deg, #1B3A5C, #3A6B9C); }
.news-card:nth-child(4) .news-card-image { background: linear-gradient(135deg, #8B1A2B, #C41E3A); }
.news-card-body { padding: 24px; }
.news-card-body h3 { font-size: 1.05rem; color: var(--navy); margin-bottom: 10px; }
.news-card-body p { font-size: 0.9rem; color: var(--gray-700); line-height: 1.6; }

/* ── Donate CTA ──────────────────────────────────────────────── */
.donate-cta { background: var(--navy); color: var(--white); }
.donate-cta .section-title { color: var(--white); }
.donate-cta .section-body { color: rgba(255,255,255,0.85); }
.impact-table { margin-top: 36px; width: 100%; max-width: 700px; }
.impact-table .row { display: flex; justify-content: space-between; align-items: center; padding: 16px 20px; border-bottom: 1px solid rgba(255,255,255,0.12); font-size: 0.95rem; }
.impact-table .row .amount { font-weight: 700; font-family: var(--font-heading); font-size: 1.05rem; min-width: 80px; }
.donate-cta .btn { margin-top: 32px; }

/* ── Footer ──────────────────────────────────────────────────── */
.site-footer { background: #0D1A26; color: rgba(255,255,255,0.7); padding: 64px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 40px; margin-bottom: 48px; }
.footer-col h4 { color: var(--white); font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 16px; }
.footer-col a { display: block; color: rgba(255,255,255,0.6); font-size: 0.88rem; padding: 4px 0; transition: color 0.15s; }
.footer-col a:hover { color: var(--white); text-decoration: none; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; font-size: 0.82rem; }
.footer-social { display: flex; gap: 16px; }
.footer-social a { color: rgba(255,255,255,0.5); font-size: 1.1rem; transition: color 0.15s; }
.footer-social a:hover { color: var(--white); }

/* ── Donation Modal ──────────────────────────────────────────── */
.modal-overlay {
  position: fixed; inset: 0; z-index: 2000; background: rgba(0,0,0,0.6);
  display: flex; align-items: center; justify-content: center; padding: 24px;
  opacity: 0; visibility: hidden; transition: all 0.25s;
}
.modal-overlay.open { opacity: 1; visibility: visible; }
.modal {
  background: var(--white); border-radius: 12px; padding: 40px 32px;
  max-width: 520px; width: 100%; position: relative; max-height: 90vh; overflow-y: auto;
  box-shadow: 0 20px 60px rgba(0,0,0,0.3);
}
.modal-close {
  position: absolute; top: 16px; right: 20px; background: none; border: none;
  font-size: 1.6rem; cursor: pointer; color: var(--gray-500); line-height: 1;
}
.modal-close:hover { color: var(--gray-900); }
.modal h2 { font-size: 1.6rem; color: var(--navy); margin-bottom: 8px; }
.modal .modal-subtitle { color: var(--gray-700); margin-bottom: 28px; font-size: 0.95rem; }
.amount-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 20px; }
.amount-option { padding: 16px 8px; border: 2px solid var(--gray-200); border-radius: 8px; background: var(--white); cursor: pointer; text-align: center; font-weight: 700; font-size: 1.1rem; color: var(--navy); transition: all 0.15s; font-family: var(--font-body); }
.amount-option:hover { border-color: var(--red); }
.amount-option.selected { border-color: var(--red); background: #FFF5F5; color: var(--red); }
.amount-option .impact { display: block; font-weight: 400; font-size: 0.7rem; color: var(--gray-500); margin-top: 4px; line-height: 1.3; }
.custom-input { width: 100%; padding: 14px 16px; border: 2px solid var(--gray-200); border-radius: 8px; font-size: 1rem; margin-bottom: 20px; font-family: var(--font-body); }
.custom-input:focus { outline: none; border-color: var(--navy); }
.frequency-toggle { display: flex; gap: 0; margin-bottom: 24px; border: 2px solid var(--gray-200); border-radius: 8px; overflow: hidden; }
.frequency-toggle button { flex: 1; padding: 12px; background: var(--white); border: none; cursor: pointer; font-weight: 600; font-size: 0.9rem; color: var(--gray-700); transition: all 0.15s; font-family: var(--font-body); }
.frequency-toggle button.active { background: var(--navy); color: var(--white); }
.modal .btn-full { width: 100%; padding: 16px; font-size: 1.05rem; }

/* ── Responsive: Tablet ──────────────────────────────────────── */
@media (max-width: 1024px) {
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .involve-grid { grid-template-columns: 1fr; max-width: 500px; margin-left: auto; margin-right: auto; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ── Responsive: Mobile ──────────────────────────────────────── */
@media (max-width: 768px) {
  .nav-main, .utility-nav { display: none; }
  .hamburger { display: flex; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: 24px; }
  .hero-content { padding: 60px 0; }
  .hero h1 { font-size: 1.9rem; }
  .hero p { font-size: 1rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; }
  .news-card { flex: 0 0 100%; min-width: 100%; margin-right: 16px; }
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .section { padding: 56px 0; }
  .amount-grid { grid-template-columns: repeat(2, 1fr); }
  .modal { padding: 28px 20px; }
  .impact-table .row { flex-direction: column; align-items: flex-start; gap: 4px; }
}
</style>
</head>
