<script>
/* ── Mobile Menu ─────────────────────── */
function toggleMobileMenu() {
  document.getElementById('hamburger').classList.toggle('active');
  document.getElementById('mobileNav').classList.toggle('open');
}

document.querySelectorAll('.mobile-nav a').forEach(function(link) {
  link.addEventListener('click', function() {
    document.getElementById('hamburger').classList.remove('active');
    document.getElementById('mobileNav').classList.remove('open');
  });
});

/* ── Accordion ────────────────────────── */
function toggleAccordion(header) {
  var item = header.parentElement;
  var isOpen = item.classList.contains('open');
  closeAllAccordions();
  if (!isOpen) {
    item.classList.add('open');
  }
}

function closeAllAccordions() {
  document.querySelectorAll('.accordion-item').forEach(function(item) {
    item.classList.remove('open');
  });
}

/* ── News Carousel ────────────────────── */
var carouselIndex = 0;
var slidesPerView = 2;

function updateSlidesPerView() {
  slidesPerView = window.innerWidth <= 768 ? 1 : 2;
}

function moveCarousel(dir) {
  updateSlidesPerView();
  var slides = document.getElementById('carouselSlides');
  var totalSlides = slides.children.length;
  var maxIndex = totalSlides - slidesPerView;
  carouselIndex = Math.max(0, Math.min(carouselIndex + dir, maxIndex));
  var slideWidth = slides.children[0].offsetWidth + 28;
  slides.style.transform = 'translateX(' + (-carouselIndex * slideWidth) + 'px)';
}

window.addEventListener('resize', function() {
  updateSlidesPerView();
  moveCarousel(0);
});

updateSlidesPerView();

/* ── Donation Modal ───────────────────── */
var selectedAmount = '25';
var selectedCustom = false;
var frequency = 'once';

function openDonateModal() {
  document.getElementById('donateModal').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeDonateModal() {
  document.getElementById('donateModal').classList.remove('open');
  document.body.style.overflow = '';
}

document.getElementById('donateModal').addEventListener('click', function(e) {
  if (e.target === this) closeDonateModal();
});

function selectAmount(btn, amount) {
  selectedCustom = false;
  selectedAmount = amount;
  document.getElementById('customAmount').style.display = 'none';
  document.querySelectorAll('#amountGrid .amount-option').forEach(function(b) { b.classList.remove('selected'); });
  btn.classList.add('selected');
}

function selectCustomAmount(btn) {
  selectedCustom = true;
  document.querySelectorAll('#amountGrid .amount-option').forEach(function(b) { b.classList.remove('selected'); });
  btn.classList.add('selected');
  document.getElementById('customAmount').style.display = 'block';
  document.getElementById('customAmount').focus();
}

function onCustomAmountInput() {
  selectedAmount = document.getElementById('customAmount').value;
}

function setFrequency(btn, freq) {
  frequency = freq;
  document.querySelectorAll('#frequencyToggle button').forEach(function(b) { b.classList.remove('active'); });
  btn.classList.add('active');
}

function submitDonation() {
  var amount = selectedCustom ? (document.getElementById('customAmount').value || '0') : selectedAmount;
  if (amount === '0' || amount === '') {
    alert('Please select or enter a donation amount.');
    return;
  }
  alert('Thank you for your ' + frequency + ' donation of $' + Number(amount).toLocaleString() + '! You are making a real difference in the lives of people affected by disasters worldwide.');
  closeDonateModal();
}

/* ── Animated Counters ───────────────── */
function animateCounters() {
  var counters = document.querySelectorAll('.stat-number');
  var animated = false;

  function run() {
    if (animated) return;
    var section = document.querySelector('.impact-stats');
    var rect = section.getBoundingClientRect();
    if (rect.top < window.innerHeight - 100) {
      animated = true;
      counters.forEach(function(el) {
        var target = parseFloat(el.getAttribute('data-target'));
        var suffix = el.getAttribute('data-suffix') || '';
        var prefix = el.getAttribute('data-prefix') || '';
        var format = el.getAttribute('data-format');
        var duration = 2000;
        var startTime = null;

        function step(ts) {
          if (!startTime) startTime = ts;
          var progress = Math.min((ts - startTime) / duration, 1);
          var eased = 1 - Math.pow(1 - progress, 3);
          var current = target * eased;

          if (format === 'comma') {
            el.textContent = Math.floor(current).toLocaleString() + suffix;
          } else if (target >= 100) {
            el.textContent = prefix + Math.floor(current).toLocaleString() + suffix;
          } else if (target < 100 && suffix === 'M') {
            el.textContent = prefix + current.toFixed(1) + suffix;
          } else {
            el.textContent = prefix + Math.floor(current) + suffix;
          }

          if (progress < 1) {
            requestAnimationFrame(step);
          } else {
            if (format === 'comma') {
              el.textContent = target.toLocaleString() + suffix;
            } else if (suffix === 'M' && target < 100) {
              el.textContent = prefix + target + suffix;
            } else {
              el.textContent = prefix + target.toLocaleString() + suffix;
            }
          }
        }
        requestAnimationFrame(step);
      });
    }
  }

  window.addEventListener('scroll', run);
  run();
}

animateCounters();

